{
  "$schema": "https://opencode.ai/config.json",
  "instructions": [
    "AGENTS.md"
  ],
  "permission": {
    "skill": {
      "*": "allow"
    }
  }
}

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const skillsDir = path.resolve(__dirname, "../skills");
const bootstrapSkillPath = path.join(skillsDir, "harness-plan", "SKILL.md");
const marker = "HARNESS_BOOTSTRAP";

let bootstrapCache;
let bootstrapReadCount = 0;

function stripFrontmatter(content) {
  return content.replace(/^---\n[\s\S]*?\n---\n?/, "").trim();
}

function getBootstrapContent() {
  if (bootstrapCache !== undefined) {
    return bootstrapCache;
  }

  if (!fs.existsSync(bootstrapSkillPath)) {
    bootstrapCache = null;
    return bootstrapCache;
  }

  bootstrapReadCount += 1;
  const body = stripFrontmatter(fs.readFileSync(bootstrapSkillPath, "utf8"));
  bootstrapCache = `<${marker}>
Claude Code Harness workflows are available through OpenCode skills.

Use OpenCode's native skill tool to load the right Harness workflow:
- harness-plan for evidence-backed planning
- harness-work for Plans.md execution
- harness-review for independent review
- harness-release for release and handoff checks
- harness-setup for setup checks
- breezing for team execution mode

Tool mapping:
- Claude Skill tool -> OpenCode native skill tool
- Claude Task/subagent routing -> OpenCode subagent facilities when available
- Claude hook parity is not claimed for OpenCode

Boundary: not_observed != absent. Runtime smoke absence keeps OpenCode at
internal-compatible; it is not public supported parity.

Reference content:
${body}
</${marker}>`;
  return bootstrapCache;
}

function firstUserMessage(output) {
  if (!output || !Array.isArray(output.messages)) {
    return null;
  }
  return output.messages.find((message) => message.info && message.info.role === "user") || null;
}

function hasBootstrap(message) {
  return Boolean(
    message &&
      Array.isArray(message.parts) &&
      message.parts.some((part) => part && part.type === "text" && String(part.text || "").includes(marker))
  );
}

export const HarnessBootstrapPlugin = async () => ({
  config: async (config) => {
    config.skills = config.skills || {};
    config.skills.paths = config.skills.paths || [];
    if (!config.skills.paths.includes(skillsDir)) {
      config.skills.paths.push(skillsDir);
    }
  },

  "experimental.chat.messages.transform": async (_input, output) => {
    const bootstrap = getBootstrapContent();
    if (!bootstrap) {
      return;
    }

    const message = firstUserMessage(output);
    if (!message || !Array.isArray(message.parts) || message.parts.length === 0 || hasBootstrap(message)) {
      return;
    }

    const ref = message.parts[0];
    message.parts.unshift({ ...ref, type: "text", text: bootstrap });
  }
});

export function __resetHarnessBootstrapCacheForTest() {
  bootstrapCache = undefined;
  bootstrapReadCount = 0;
}

export function __getHarnessBootstrapReadCountForTest() {
  return bootstrapReadCount;
}

export function __getHarnessBootstrapContentForTest() {
  return getBootstrapContent();
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://claude-code-harness.local/schemas/acceptance-context.v1.schema.json",
  "title": "acceptance-context.v1",
  "description": "Acceptance Demo 用の context 構造体。harness-accept skill が Plan Brief 側 personal-preference.v1 と user_request_hash で join して組み立てる。",
  "type": "object",
  "required": [
    "schema",
    "user_request",
    "user_request_hash",
    "demo_artifacts",
    "verified_criteria",
    "unverified_caveats",
    "past_issue_patterns",
    "recommendation",
    "recommendation_evidence",
    "project",
    "generated_at"
  ],
  "additionalProperties": false,
  "properties": {
    "schema": {
      "type": "string",
      "const": "acceptance-context.v1"
    },
    "user_request": {
      "type": "string",
      "minLength": 1
    },
    "user_request_hash": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}$",
      "description": "Plan Brief 側 personal-preference.v1.data.user_request_hash と join するキー"
    },
    "demo_artifacts": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["kind", "path"],
        "additionalProperties": false,
        "properties": {
          "kind": {
            "type": "string",
            "enum": ["video", "screenshot", "text"]
          },
          "path": { "type": "string" }
        }
      }
    },
    "verified_criteria": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["name", "passed", "evidence"],
        "additionalProperties": false,
        "properties": {
          "name": { "type": "string" },
          "passed": { "type": "boolean" },
          "evidence": {
            "type": "string",
            "description": "空文字列の場合 HTML 上で警告表示される (DoD c)"
          }
        }
      }
    },
    "unverified_caveats": {
      "type": "array",
      "items": { "type": "string" }
    },
    "past_issue_patterns": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["pattern_id", "title"],
        "additionalProperties": false,
        "properties": {
          "pattern_id": { "type": "string" },
          "title": { "type": "string" },
          "verified_in_current_task": { "type": "boolean" }
        }
      }
    },
    "recommendation": {
      "type": "string",
      "enum": ["ship", "wait", "reject"]
    },
    "recommendation_evidence": {
      "type": "array",
      "items": { "type": "string" }
    },
    "project": {
      "type": "string",
      "minLength": 1
    },
    "generated_at": {
      "type": "string",
      "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$"
    },
    "verified_criteria_items": {
      "type": "array",
      "description": "Derived rendering helper for render-html.sh. Wraps verified_criteria with display attributes (status_label, evidence_warn 等). Compile / skill が populate。Optional: not required by canonical context.",
      "items": {
        "type": "object",
        "required": ["name", "status_label"],
        "additionalProperties": false,
        "properties": {
          "name": { "type": "string" },
          "status_label": { "type": "string" },
          "evidence": { "type": "string" },
          "evidence_warn": { "type": "string" }
        }
      }
    },
    "recommendation_evidence_items": {
      "type": "array",
      "description": "Derived rendering helper for render-html.sh. Wraps recommendation_evidence string[] as [{text}].",
      "items": {
        "type": "object",
        "required": ["text"],
        "additionalProperties": false,
        "properties": {
          "text": { "type": "string" }
        }
      }
    },
    "unverified_caveats_items": {
      "type": "array",
      "description": "Derived rendering helper for render-html.sh. Wraps unverified_caveats string[] as [{text}].",
      "items": {
        "type": "object",
        "required": ["text"],
        "additionalProperties": false,
        "properties": {
          "text": { "type": "string" }
        }
      }
    },
    "blind_evaluation": {
      "type": "object",
      "description": "Optional (Phase 137.2, additive). Fresh fork 評価者 (rubric/合格ライン/途中経過なし) による第一印象。説得系/文書系の成果物のみ実行し、機能系タスクは applicable=false でスキップする。",
      "required": ["applicable", "eligibility_reason"],
      "additionalProperties": false,
      "properties": {
        "applicable": {
          "type": "boolean",
          "description": "Eligibility を満たし評価者を起動したか。false なら以下の evaluator_* / divergence は省略可"
        },
        "eligibility_reason": {
          "type": "string",
          "enum": ["persuasive-doc", "functional-skip", "not_applicable", "unavailable"]
        },
        "audience_purpose_line": {
          "type": "string",
          "description": "評価者に渡した読者/目的 1 行 (監査用にそのまま記録)"
        },
        "evaluator_believable": {
          "type": "string",
          "enum": ["believable", "not_believable", "uncertain"]
        },
        "evaluator_useful": {
          "type": "string",
          "enum": ["useful", "not_useful", "uncertain"]
        },
        "evaluator_friction_points": {
          "type": "array",
          "items": { "type": "string" }
        },
        "internal_recommendation": {
          "type": "string",
          "enum": ["ship", "wait", "reject"],
          "description": "blind_evaluation 補正前の recommendation (pending 補正後・interim 値)"
        },
        "divergence": {
          "type": "string",
          "enum": ["none", "internal_high_evaluator_low", "internal_low_evaluator_high"]
        },
        "divergence_notes": { "type": "string" }
      }
    },
    "blind_evaluation_items": {
      "type": "array",
      "description": "Derived rendering helper for render-html.sh. divergence != none のときだけ 0/1 件を populate する (Phase 137.2)。",
      "items": {
        "type": "object",
        "required": ["divergence_label", "audience_purpose_line", "evaluator_believable", "evaluator_useful", "friction_points_text", "divergence_notes"],
        "additionalProperties": false,
        "properties": {
          "divergence_label": { "type": "string" },
          "audience_purpose_line": { "type": "string" },
          "evaluator_believable": { "type": "string" },
          "evaluator_useful": { "type": "string" },
          "friction_points_text": { "type": "string" },
          "divergence_notes": { "type": "string" }
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://claude-code-harness.local/schemas/plan-brief-context.v1.schema.json",
  "title": "plan-brief-context.v1",
  "description": "Plan Brief 用の context 構造体。confidence は互換名として残すが、意味は plan_readiness (DoD 明確度 + 依存解決率) に限定する。",
  "type": "object",
  "required": [
    "schema",
    "user_request",
    "my_understanding",
    "options",
    "risks",
    "acceptance_criteria",
    "confidence",
    "confidence_evidence",
    "related_decisions",
    "similar_past_plans",
    "project",
    "generated_at"
  ],
  "additionalProperties": false,
  "properties": {
    "schema": {
      "type": "string",
      "const": "plan-brief-context.v1"
    },
    "user_request": {
      "type": "string",
      "minLength": 1
    },
    "my_understanding": {
      "type": "string"
    },
    "options": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["name", "summary"],
        "additionalProperties": false,
        "properties": {
          "name": { "type": "string" },
          "summary": { "type": "string" },
          "pros": {
            "type": "array",
            "items": { "type": "string" }
          },
          "cons": {
            "type": "array",
            "items": { "type": "string" }
          }
        }
      }
    },
    "risks": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["kind", "severity", "description"],
        "additionalProperties": false,
        "properties": {
          "kind": { "type": "string" },
          "severity": {
            "type": "string",
            "enum": ["info", "warn", "critical"]
          },
          "description": { "type": "string" },
          "mitigation": { "type": "string" }
        }
      }
    },
    "acceptance_criteria": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["id", "description"],
        "additionalProperties": false,
        "properties": {
          "id": { "type": "string" },
          "description": { "type": "string" },
          "verifiable_by": { "type": "string" }
        }
      }
    },
    "confidence": {
      "type": "integer",
      "description": "Backward-compatible field name for plan_readiness. Score only DoD clarity plus dependency resolution; do not add similar-plan success rate or D/P count as separate axes.",
      "minimum": 0,
      "maximum": 100
    },
    "confidence_evidence": {
      "type": "array",
      "description": "Evidence for plan_readiness: DoD clarity, dependency resolution, and context-only notes. Must not imply AI understanding or success probability.",
      "items": { "type": "string" }
    },
    "related_decisions": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["id", "title"],
        "additionalProperties": false,
        "properties": {
          "id": { "type": "string" },
          "title": { "type": "string" },
          "relevance": { "type": "string" }
        }
      }
    },
    "similar_past_plans": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["archive_path", "phase"],
        "additionalProperties": false,
        "properties": {
          "archive_path": { "type": "string" },
          "phase": { "type": "string" },
          "outcome": {
            "type": "string",
            "enum": ["cc:完了", "cc:WIP", "cc:TODO", "skipped", "unknown"]
          },
          "relevance": { "type": "string" }
        }
      }
    },
    "project": {
      "type": "string",
      "minLength": 1
    },
    "generated_at": {
      "type": "string",
      "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$"
    },
    "confidence_evidence_items": {
      "type": "array",
      "description": "Derived rendering helper for render-html.sh. Each string in confidence_evidence is wrapped as {text: <string>} so the template can iterate via {{#confidence_evidence_items}}{{text}}{{/confidence_evidence_items}}. The compile script (Phase 65.1.3) populates this. Optional: not required by canonical context.",
      "items": {
        "type": "object",
        "required": ["text"],
        "additionalProperties": false,
        "properties": {
          "text": { "type": "string" }
        }
      }
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "orchestration-ledger.v1",
  "title": "Orchestration Ledger Entry (v1)",
  "description": "One append-only line per backend delegation, written by codex-companion.sh / cursor-companion.sh. Records only fixed, non-sensitive scalars — never prompt text, file contents, or secrets. See spec.md 'Orchestration Visibility Contract'.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "ts",
    "backend",
    "subcommand",
    "write",
    "exit_code",
    "duration_ms",
    "session_id",
    "counts"
  ],
  "properties": {
    "ts": {
      "type": "string",
      "format": "date-time",
      "description": "UTC timestamp when the delegation was recorded (ISO 8601, e.g. 2026-06-03T06:00:00Z)."
    },
    "backend": {
      "type": "string",
      "enum": ["codex", "cursor"],
      "description": "Which non-Claude backend was delegated to. Claude-side work is not written here; it is derived from agent-trace.jsonl at scorecard time."
    },
    "subcommand": {
      "type": "string",
      "description": "The companion subcommand (task, review, adversarial-review, setup, status, result, cancel)."
    },
    "write": {
      "type": "boolean",
      "description": "Whether the delegation had write intent (e.g. task --write). Read-only delegations are false."
    },
    "exit_code": {
      "type": ["integer", "null"],
      "description": "Process exit code of the delegation. Null when the companion exec()s into the backend and cannot post-process (codex path)."
    },
    "duration_ms": {
      "type": ["integer", "null"],
      "description": "Wall-clock duration in milliseconds. Null when not capturable (codex exec path)."
    },
    "session_id": {
      "type": "string",
      "description": "Session that issued the delegation (CLAUDE_SESSION_ID, else session.json, else 'unknown'). Used to scope the scorecard to the current session."
    },
    "counts": {
      "type": "boolean",
      "description": "True only for real delegations (task / review / adversarial-review). False for status / setup / result / cancel so polling does not inflate the score."
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "orchestration-scorecard.v1",
  "title": "Orchestration Scorecard (v1)",
  "description": "Merged view of the current session's backend mix (from the ledger) and lifetime totals (from the accumulator), produced by scripts/orchestration-scorecard.sh. Claude is the host runtime and is never counted as a delegation; the headline figures are Codex/Cursor delegation counts. See spec.md 'Orchestration Visibility Contract'.",
  "type": "object",
  "additionalProperties": false,
  "required": ["version", "session_id", "observed", "session", "lifetime", "note"],
  "properties": {
    "version": { "type": "integer", "const": 1 },
    "session_id": { "type": "string" },
    "observed": {
      "type": "boolean",
      "description": "False when no counted delegation exists in either scope; surfaces degrade to 'no delegations observed'."
    },
    "session": {
      "type": "object",
      "additionalProperties": false,
      "required": ["codex", "cursor", "claude", "non_claude_delegations", "backends_engaged"],
      "properties": {
        "codex": { "$ref": "#/definitions/backendSlot" },
        "cursor": { "$ref": "#/definitions/backendSlot" },
        "claude": {
          "type": "object",
          "additionalProperties": false,
          "required": ["status"],
          "properties": {
            "status": { "type": "string", "const": "host", "description": "Claude is the host runtime; its work is not delegation-counted." }
          }
        },
        "non_claude_delegations": { "type": "integer", "minimum": 0, "description": "Codex + Cursor counted delegations this session." },
        "backends_engaged": { "type": "integer", "minimum": 1, "maximum": 3, "description": "Distinct backends active this session, including the Claude host (1) plus each of Codex/Cursor used." }
      }
    },
    "lifetime": {
      "type": "object",
      "additionalProperties": false,
      "required": ["codex", "cursor", "non_claude_delegations"],
      "properties": {
        "codex": { "type": "object", "required": ["count"], "additionalProperties": false, "properties": { "count": { "type": "integer", "minimum": 0 } } },
        "cursor": { "type": "object", "required": ["count"], "additionalProperties": false, "properties": { "count": { "type": "integer", "minimum": 0 } } },
        "non_claude_delegations": { "type": "integer", "minimum": 0, "description": "Cumulative Codex + Cursor delegations across rolled-up sessions." }
      }
    },
    "note": { "type": "string", "description": "One-line reading aid for the figures." }
  },
  "definitions": {
    "backendSlot": {
      "type": "object",
      "additionalProperties": false,
      "required": ["count", "status"],
      "properties": {
        "count": { "type": "integer", "minimum": 0 },
        "status": {
          "type": "string",
          "enum": ["used", "available", "not-configured"],
          "description": "used = count>0; available = configured but unused this session; not-configured = backend binary absent (neutral, not a failure)."
        }
      }
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "orchestration-totals.v1",
  "title": "Orchestration Lifetime Totals (v1)",
  "description": "Project-scoped cumulative per-backend delegation totals, accumulated across sessions by scripts/orchestration-rollup.sh. Each rollup reconciles a session's contribution by the delta between its current ledger count and the amount already folded in (session_counts), so completion + session-end + re-runs — even mid-session — add each delegation exactly once: no new delegations is a no-op, a grown ledger adds only the tail. Record-only; the scorecard reads this for the lifetime figure.",
  "type": "object",
  "additionalProperties": false,
  "required": ["version", "totals", "rolled_up_sessions", "first_seen", "last_seen"],
  "properties": {
    "version": {
      "type": "integer",
      "const": 1,
      "description": "Schema version."
    },
    "totals": {
      "type": "object",
      "description": "Cumulative count of counted delegations per backend across all rolled-up sessions.",
      "additionalProperties": {
        "type": "integer",
        "minimum": 0
      }
    },
    "rolled_up_sessions": {
      "type": "array",
      "description": "Session ids that have been folded into totals at least once. Used together with session_counts to reconcile a session by delta on re-rollup; for a pre-reconciliation file a member with no session_counts entry is treated as already fully counted (delta 0).",
      "items": { "type": "string" }
    },
    "session_counts": {
      "type": "object",
      "description": "Per-session snapshot of the per-backend amounts already folded into totals. On re-rollup the script adds only (current ledger count − this snapshot) per backend, then overwrites the snapshot with the current count — so a session whose ledger grew after an earlier (e.g. mid-session) rollup is reconciled without double-counting. Additive in v1: absent in pre-reconciliation files and read as {}; not required.",
      "additionalProperties": {
        "type": "object",
        "additionalProperties": {
          "type": "integer",
          "minimum": 0
        }
      }
    },
    "first_seen": {
      "type": ["string", "null"],
      "format": "date-time",
      "description": "UTC timestamp of the first rollup (ISO 8601). Null before any rollup."
    },
    "last_seen": {
      "type": ["string", "null"],
      "format": "date-time",
      "description": "UTC timestamp of the most recent rollup (ISO 8601)."
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://claude-code-harness.local/schemas/progress-snapshot.v1.schema.json",
  "title": "progress-snapshot.v1",
  "description": "Progress Tracker (Phase 65.4) の進捗 snapshot 構造体。harness-progress skill が Plans.md と state file から組み立てる。",
  "type": "object",
  "required": [
    "schema",
    "project",
    "current_task",
    "progress_pct",
    "todo_tasks",
    "wip_tasks",
    "done_tasks",
    "elapsed_minutes",
    "estimated_total_minutes",
    "cost_so_far_usd",
    "cost_estimate_usd",
    "alerts",
    "generated_at"
  ],
  "additionalProperties": false,
  "properties": {
    "schema": {
      "type": "string",
      "const": "progress-snapshot.v1"
    },
    "project": {
      "type": "string",
      "description": "プロジェクト名 (basename of git repo)"
    },
    "current_task": {
      "type": "string",
      "description": "現在進行中のタスク 1 行サマリ (cc:WIP の最初の項目)。WIP がない場合は空文字"
    },
    "progress_pct": {
      "type": "integer",
      "minimum": 0,
      "maximum": 100,
      "description": "完了率 (cc:完了 ÷ (TODO+WIP+完了) × 100、四捨五入)"
    },
    "todo_tasks": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["number", "title"],
        "additionalProperties": false,
        "properties": {
          "number": {"type": "string"},
          "title": {"type": "string"}
        }
      }
    },
    "wip_tasks": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["number", "title"],
        "additionalProperties": false,
        "properties": {
          "number": {"type": "string"},
          "title": {"type": "string"}
        }
      }
    },
    "done_tasks": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["number", "title", "commit"],
        "additionalProperties": false,
        "properties": {
